import datetime,hashlib,json,subprocess
root=Path(__file__).resolve().parent
repo=Path('C:/Users/Marko/Desktop/Projects/llmx-model-validation')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
manifest=json.loads((root/'source-manifest.json').read_text())
assert all(sha(root/p)==h for p,h in manifest['files'].items())
for name in ['windows-validation/result.json','linux-validation/report.json','active-hf-results/report.json','long-results/report.json','long-run.json']:
    assert json.loads((root/name).read_text())['status']=='pass',name
extensions={'.json','.py','.bat','.txt','.cpp','.hpp','.stdout','.stderr'}
files=[p for p in root.iterdir() if p.is_file() and p.suffix in extensions]
for folder in ['windows-validation','linux-validation','active-hf-results','long-results']:
    files += [p for p in (root/folder).rglob('*') if p.is_file() and p.suffix in extensions]
for arm in ['control','candidate','candidate-enabled']:
    for rel in manifest['changed_files']:
        p=root/arm/rel
        if p.exists():files.append(p)
reports={}
for p in sorted(set(files)):
    raw=p.read_bytes();row={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
    if p.suffix=='.json':row['data']=json.loads(raw)
    else:row['text']=raw.decode('utf-8',errors='replace')
    reports[p.relative_to(root).as_posix()]=row
artifact={'schema':1,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_base':manifest['base'],'scope':'Scratch placement integration onto validated current production. Production runtime unchanged. All regression jobs terminal; no fresh accepted timing or merge.','results':{'windows_native':'10/10','windows_required_hf':'11/11','linux_native':'10/10','linux_required_hf':'11/11','active_windows_hf':'28/28','long_0_6b':'F32/Q8 each33 exact vectors, 5013888 finite floats per arm; unchanged HF bounds'},'limits':['No production placement integration','Current-source followup1/9 placement witnesses and optional 8B consumer not rerun','No accepted performance measurements; seven old-source busy preflights retained separately','No DRAM bandwidth measurements or resolved sub-percent observer effects','No full-corpus/max-context/8B-long claim'],'reports':reports}
path=repo/'docs/benchmarks/prefill-current-integration-20260920.json'
path.write_text(json.dumps(artifact,indent=2,ensure_ascii=True)+'\n',encoding='ascii')
print(len(reports),'records',path.stat().st_size,'bytes',sha(path))

