#define NOMINMAX
#include <windows.h>
#include "llama.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string_view>
#include <thread>
#include <vector>

using Clock = std::chrono::steady_clock;

static double counter_seconds() {
    static const double frequency = [] {
        LARGE_INTEGER value;
        if (!QueryPerformanceFrequency(&value)) throw std::runtime_error("QPC frequency unavailable");
        return double(value.QuadPart);
    }();
    LARGE_INTEGER value;
    if (!QueryPerformanceCounter(&value)) throw std::runtime_error("QPC unavailable");
    return double(value.QuadPart) / frequency;
}

struct BackendLifetime {
    BackendLifetime() { llama_backend_init(); }
    ~BackendLifetime() { llama_backend_free(); }
};

int main(int argc, char** argv) {
    try {
        if (argc != 6) throw std::runtime_error("usage: mx-model MODEL TOKENS OUTPUT mx primary|followup1|followup9");
        const std::string_view mode(argv[4]), workload(argv[5]);
        if (mode != "mx") throw std::runtime_error("wrong executable for mode");
        const size_t pp_tokens = workload == "primary" ? 215 : workload == "followup1" ? 1 : workload == "followup9" ? 9 : 0;
        if (!pp_tokens) throw std::runtime_error("invalid workload");
        std::ifstream input(argv[2]);
        std::vector<llama_token> ids;
        llama_token id;
        while (input >> id) ids.push_back(id);
        if (!input.eof() || ids.size() != 247) throw std::runtime_error("expected247 valid pinned tokens");

        BackendLifetime backend;
        auto mp = llama_model_default_params();
        mp.n_gpu_layers = 0;
        mp.load_mode = LLAMA_LOAD_MODE_NONE;
        std::unique_ptr<llama_model, decltype(&llama_model_free)> model(llama_model_load_from_file(argv[1], mp), &llama_model_free);
        if (!model) throw std::runtime_error("model load failed");
        auto cp = llama_context_default_params();
        cp.n_ctx = 512;
        cp.n_batch = 215;
        cp.n_ubatch = 128;
        cp.n_threads = cp.n_threads_batch = 6;
        cp.n_seq_max = 1;
        cp.type_k = cp.type_v = GGML_TYPE_F32;
        cp.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_DISABLED;
        cp.offload_kqv = cp.op_offload = false;
        cp.embeddings = false;
        std::unique_ptr<llama_context, decltype(&llama_free)> ctx(llama_init_from_model(model.get(), cp), &llama_free);
        if (!ctx) throw std::runtime_error("context creation failed");
        if (llama_n_threads(ctx.get()) != 6 || llama_n_threads_batch(ctx.get()) != 6 ||
            llama_n_ubatch(ctx.get()) != 128 || llama_n_batch(ctx.get()) < 215 || llama_n_ctx(ctx.get()) < 247)
            throw std::runtime_error("unexpected effective context settings");
        const size_t nv = llama_vocab_n_tokens(llama_model_get_vocab(model.get()));
        if (!nv || std::any_of(ids.begin(), ids.end(), [nv](llama_token token) { return token < 0 || size_t(token) >= nv; }))
            throw std::runtime_error("invalid token ID or vocabulary");
        const size_t prefix_tokens = 215 - pp_tokens;
        std::vector<float> warmup, final;
        struct Record { double pp, tg, begin, prefill_end, end; uint64_t hash; };
        Record records[2]{};
        for (int run = 0; run < 2; ++run) {
            llama_memory_clear(llama_get_memory(ctx.get()), true);
            if (prefix_tokens) {
                if (llama_decode(ctx.get(), llama_batch_get_one(ids.data(), int32_t(prefix_tokens))))
                    throw std::runtime_error("prefix decode failed");
                llama_synchronize(ctx.get());
            }
            if (llama_memory_seq_pos_max(llama_get_memory(ctx.get()), 0) != llama_pos(prefix_tokens) - 1)
                throw std::runtime_error("prefix position mismatch");
            records[run].begin = counter_seconds();
            auto start = Clock::now();
            if (llama_decode(ctx.get(), llama_batch_get_one(ids.data() + prefix_tokens, int32_t(pp_tokens))))
                throw std::runtime_error("prefill decode failed");
            llama_synchronize(ctx.get());
            auto pp_end = Clock::now();
            records[run].prefill_end = counter_seconds();
            for (size_t i = 215; i < ids.size(); ++i) {
                if (llama_decode(ctx.get(), llama_batch_get_one(&ids[i], 1)))
                    throw std::runtime_error("continuation decode failed");
                llama_synchronize(ctx.get());
            }
            auto tg_end = Clock::now();
            records[run].end = counter_seconds();
            records[run].pp = std::chrono::duration<double, std::milli>(pp_end - start).count();
            records[run].tg = std::chrono::duration<double, std::milli>(tg_end - pp_end).count();
            if (llama_memory_seq_pos_max(llama_get_memory(ctx.get()), 0) != 246)
                throw std::runtime_error("final position mismatch");
            const float* values = llama_get_logits_ith(ctx.get(), -1);
            if (!values) throw std::runtime_error("missing final logits");
            uint64_t hash = 14695981039346656037ull;
            for (size_t i = 0; i < nv; ++i) {
                if (!std::isfinite(values[i])) throw std::runtime_error("nonfinite logit");
                uint32_t bits;
                std::memcpy(&bits, values + i, 4);
                for (int shift = 0; shift < 32; shift += 8) {
                    hash ^= (bits >> shift) & 255;
                    hash *= 1099511628211ull;
                }
            }
            records[run].hash = hash;
            if (!run) warmup.assign(values, values + nv);
            else {
                if (std::memcmp(values, warmup.data(), nv * sizeof(float)))
                    throw std::runtime_error("warmup/final vector differs");
                final.assign(values, values + nv);
            }
        }
        std::ofstream output(argv[3], std::ios::binary);
        output.exceptions(std::ios::badbit | std::ios::failbit);
        output.write(reinterpret_cast<const char*>(final.data()), std::streamsize(final.size() * sizeof(float)));
        output.close();
        std::cout << std::setprecision(15) << "{\"caller_thread_id\":" << std::hash<std::thread::id>{}(std::this_thread::get_id())
                  << ",\"mode\":\"mx\",\"workload\":\"" << workload << "\",\"threads\":6,\"ubatch\":128,\"pp_tokens\":"
                  << pp_tokens << ",\"tg_tokens\":32,\"vocab\":" << final.size() << ",\"records\":[";
        for (int i = 0; i < 2; ++i) {
            if (i) std::cout << ',';
            const auto& r = records[i];
            std::cout << "{\"run\":" << i << ",\"pp_ms\":" << r.pp << ",\"tg_ms\":" << r.tg
                      << ",\"qpc_begin\":" << r.begin << ",\"qpc_prefill_end\":" << r.prefill_end << ",\"qpc_end\":"
                      << r.end << ",\"final_fnv64\":\"" << std::hex << r.hash << std::dec << "\"}";
        }
        std::cout << "]}\n";
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

