#include "witness.hpp"
#include <sstream>
#define main llmx_cli_main
#include "cli/main.cpp"
#undef main

int main(int argc, char** argv) {
    if (argc < 2 || std::string(argv[1]) != "logits") {
        std::cerr << "witness CLI accepts logits only\n";
        return 2;
    }
    witness::caller = GetCurrentThreadId();
    witness::prefill = true;
    const int result = llmx_cli_main(argc, argv);
    witness::prefill = false;
    if (result) return result;
    if (witness::applies != 6 || witness::restores != 6 || witness::caller_applies != 1) {
        std::cerr << "expected one active six-participant prefill\n";
        return 3;
    }
    try {
        std::ostringstream report;
        auto* saved = std::cout.rdbuf(report.rdbuf());
        try { witness::print(); }
        catch (...) { std::cout.rdbuf(saved); throw; }
        std::cout.rdbuf(saved);
        std::cerr << "PLACEMENT_WITNESS " << report.str() << '\n';
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 4;
    }
    return 0;
}

